                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // VARIÁVEIS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let currentQuestion = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let score = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let lives = 3;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let combo = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let correct = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let wrong = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let answered = false;


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // INICIAR JOGO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                startButton.addEventListener("click", startGame);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                restartButton.addEventListener("click", startGame);


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function startGame() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    currentQuestion = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        score = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            lives = 3;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                combo = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    correct = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        wrong = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            answered = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                updateStats();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    startScreen.classList.remove("active");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        endScreen.classList.remove("active");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            gameScreen.classList.add("active");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                showQuestion();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // MOSTRAR PERGUNTA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function showQuestion() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    answered = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        feedback.classList.add("hidden");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            submitButton.classList.add("hidden");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                answersContainer.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    inputContainer.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const question = questions[currentQuestion];


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            questionNumber.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    String(currentQuestion + 1).padStart(2, "0");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        questionType.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                question.category;


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    questionText.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            question.question;


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const progress =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        (currentQuestion / questions.length) * 100;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            progressBar.style.width =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `${progress}%`;


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // MÚLTIPLA ESCOLHA / VERDADEIRO OU FALSO

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    question.type === "multiple" ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            question.type === "truefalse"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        question.answers.forEach(answer => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const button =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.createElement("button");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                button.classList.add("answer-button");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            button.textContent = answer;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        button.addEventListener(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "click",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        () => checkAnswer(answer, button)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                answersContainer.appendChild(button);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
}

// QUESTÃO DE DIGITAÇÃO

    if (question.type === "input") {

            const input =
                        document.createElement("input");

                                input.type = "number";

                                        input.classList.add("number-input");

                                                input.placeholder = "?";

                                                        input.id = "answerInput";

                                                                inputContainer.appendChild(input);

                                                                        submitButton.classList.remove("hidden");

                                                                                input.focus();

                                                                                        input.addEventListener("keydown", event => {

                                                                                                    if (event.key === "Enter") {
                                                                                                                    checkInputAnswer();
                                                                                                                                }

                                                                                                                                        });

                                                                                                                                            }

                                                                                                                                            }


                                                                                                                                            // ========================================
                                                                                                                                            // BOTÃO CONFIRMAR
                                                                                                                                            // ========================================

                                                                                                                                            submitButton.addEventListener(
                                                                                                                                                "click",
                                                                                                                                                    checkInputAnswer
                                                                                                                                                    );


                                                                                                                                                    function checkInputAnswer() {

                                                                                                                                                        const input =
                                                                                                                                                                document.getElementById("answerInput");

                                                                                                                                                                    if (!input || input.value === "") {
                                                                                                                                                                            return;
                                                                                                                                                                                }

                                                                                                                                                                                    checkAnswer(input.value);

                                                                                                                                                                                    }


                                                                                                                                                                                    // ========================================
                                                                                                                                                                                    // VERIFICAR RESPOSTA
                                                                                                                                                                                    // ========================================

                                                                                                                                                                                    function checkAnswer(answer, selectedButton = null) {

                                                                                                                                                                                        if (answered) {
                                                                                                                                                                                                return;
                                                                                                                                                                                                    }

                                                                                                                                                                                                        answered = true;

                                                                                                                                                                                                            const question =
                                                                                                                                                                                                                    questions[currentQuestion];


                                                                                                                                                                                                                        const isCorrect =
                                                                                                                                                                                                                                String(answer).trim().toLowerCase() ===
                                                                                                                                                                                                                                        String(question.correct).trim().toLowerCase();


                                                                                                                                                                                                                                            if (isCorrect) {

                                                                                                                                                                                                                                                    handleCorrect(question, selectedButton);

                                                                                                                                                                                                                                                        } else {

                                                                                                                                                                                                                                                                handleWrong(question, selectedButton);

                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    // ========================================
                                                                                                                                                                                                                                                                    // ACERTO
                                                                                                                                                                                                                                                                    // ========================================

                                                                                                                                                                                                                                                                    function handleCorrect(question, selectedButton) {

                                                                                                                                                                                                                                                                        correct++;

                                                                                                                                                                                                                                                                            combo++;

                                                                                                                                                                                                                                                                                const points =
                                                                                                                                                                                                                                                                                        100 + ((combo - 1) * 25);

                                                                                                                                                                                                                                                                                            score += points;


                                                                                                                                                                                                                                                                                                if (selectedButton) {

                                                                                                                                                                                                                                                                                                        selectedButton.classList.add("correct");

                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                feedbackTitle.textContent =
                                                                                                                                                                                                                                                                                                                        "★ ACERTOU! ★";

                                                                                                                                                                                                                                                                                                                            feedbackTitle.style.color =
                                                                                                                                                                                                                                                                                                                                    "#39ff14";

                                                                                                                                                                                                                                                                                                                                        feedbackText.innerHTML =
                                                                                                                                                                                                                                                                                                                                                `+${points} pontos!<br><br>` +
                                                                                                                                                                                                                                                                                                                                                        `<strong>Você mandou bem!</strong>`;


                                                                                                                                                                                                                                                                                                                                                            feedback.classList.remove("hidden");


                                                                                                                                                                                                                                                                                                                                                                disableAnswers();

                                                                                                                                                                                                                                                                                                                                                                    updateStats();

                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                    // ========================================
                                                                                                                                                                                                                                                                                                                                                                    // ERRO
                                                                                                                                                                                                                                                                                                                                                                    // ========================================

                                                                                                                                                                                                                                                                                                                                                                    function handleWrong(question, selectedButton) {

                                                                                                                                                                                                                                                                                                                                                                        wrong++;

                                                                                                                                                                                                                                                                                                                                                                            lives--;

                                                                                                                                                                                                                                                                                                                                                                                combo = 0;


                                                                                                                                                                                                                                                                                                                                                                                    if (selectedButton) {

                                                                                                                                                                                                                                                                                                                                                                                            selectedButton.classList.add("wrong");

                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                    // Mostra a resposta correta

                                                                                                                                                                                                                                                                                                                                                                                                        document
                                                                                                                                                                                                                                                                                                                                                                                                                .querySelectorAll(".answer-button")
                                                                                                                                                                                                                                                                                                                                                                                                                        .forEach(button => {

                                                                                                                                                                                                                                                                                                                                                                                                                                    if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                    button.textContent.toLowerCase() ===
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    String(question.correct).toLowerCase()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                button.classList.add("correct");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        feedbackTitle.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "✖ OPS!";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    feedbackTitle.style.color =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "#ff2bd6";


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                feedbackText.innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `<strong>Resposta correta:</strong> ${question.correct}<br><br>` +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                `<strong>📚 ENTENDA:</strong><br>` +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `${question.explanation}`;


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            feedback.classList.remove("hidden");


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                disableAnswers();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    updateStats();


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (lives <= 0) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                nextButton.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "VER RESULTADO ▶";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // DESATIVAR RESPOSTAS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function disableAnswers() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .querySelectorAll(".answer-button")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .forEach(button => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                button.disabled = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            button.style.cursor = "default";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        submitButton.disabled = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

// ========================================
// PRÓXIMA PERGUNTA
// ========================================

nextButton.addEventListener(
    "click",
        nextQuestion
        );


        function nextQuestion() {

            if (lives <= 0) {

                    endGame();

                            return;

                                }


                                    currentQuestion++;


                                        if (currentQuestion >= questions.length) {

                                                endGame();

                                                        return;

                                                            }


                                                                submitButton.disabled = false;

                                                                    nextButton.textContent =
                                                                            "PRÓXIMO ▶";

                                                                                showQuestion();

                                                                                }


                                                                                // ========================================
                                                                                // ATUALIZAR ESTATÍSTICAS
                                                                                // ========================================

                                                                                function updateStats() {

                                                                                    scoreElement.textContent =
                                                                                            String(score).padStart(4, "0");


                                                                                                livesElement.textContent =
                                                                                                        "❤️".repeat(lives) +
                                                                                                                "🖤".repeat(3 - lives);


                                                                                                                    comboElement.textContent =
                                                                                                                            `x${combo}`;

                                                                                                                            }


                                                                                                                            // ========================================
                                                                                                                            // FINAL DO JOGO
                                                                                                                            // ========================================

                                                                                                                            function endGame() {

                                                                                                                                gameScreen.classList.remove("active");

                                                                                                                                    endScreen.classList.add("active");


                                                                                                                                        finalScore.textContent =
                                                                                                                                                String(score).padStart(4, "0");


                                                                                                                                                    correctAnswers.textContent =
                                                                                                                                                            correct;


                                                                                                                                                                wrongAnswers.textContent =
                                                                                                                                                                        wrong;


                                                                                                                                                                            progressBar.style.width = "100%";


                                                                                                                                                                                let message;


                                                                                                                                                                                    const percentage =
                                                                                                                                                                                            (correct / questions.length) * 100;


                                                                                                                                                                                                if (percentage === 100) {

                                                                                                                                                                                                        message =
                                                                                                                                                                                                                    "🏆 PERFEITO! Você dominou a matemática!";

                                                                                                                                                                                                                        } else if (percentage >= 70) {

                                                                                                                                                                                                                                message =
                                                                                                                                                                                                                                            "🔥 INCRÍVEL! Você está mandando muito bem!";

                                                                                                                                                                                                                                                } else if (percentage >= 50) {

                                                                                                                                                                                                                                                        message =
                                                                                                                                                                                                                                                                    "⭐ BOA! Continue praticando!";

                                                                                                                                                                                                                                                                        } else {

                                                                                                                                                                                                                                                                                message =
                                                                                                                                                                                                                                                                                            "💜 NÃO DESISTA! A prática faz a diferença!";

                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                    finalMessage.textContent =
                                                                                                                                                                                                                                                                                                            message;


                                                                                                                                                                                                                                                                                                                saveHighScore();

                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                // ========================================
                                                                                                                                                                                                                                                                                                                // HIGH SCORE
                                                                                                                                                                                                                                                                                                                // ========================================

                                                                                                                                                                                                                                                                                                                function saveHighScore() {

                                                                                                                                                                                                                                                                                                                    const oldScore =
                                                                                                                                                                                                                                                                                                                            Number(localStorage.getItem("neonMathHighScore")) || 0;


                                                                                                                                                                                                                                                                                                                                if (score > oldScore) {

                                                                                                                                                                                                                                                                                                                                        localStorage.setItem(
                                                                                                                                                                                                                                                                                                                                                    "neonMathHighScore",
                                                                                                                                                                                                                                                                                                                                                                score
                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                const highScore =
                                                                                                                                                                                                                                                                                                                                                                                        Number(localStorage.getItem("neonMathHighScore")) || 0;


                                                                                                                                                                                                                                                                                                                                                                                            highScoreElement.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                    String(highScore).padStart(4, "0");

                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                    // Carrega o recorde salvo

                                                                                                                                                                                                                                                                                                                                                                                                    saveHighScore();

